345	/* return exitcode based on SWITCH_Q setting, useful mainly in scripts */
346	int
347	returninfo()
348	{
349	#ifdef GRAPHX
350	#define VARIANT 2
351	#else
352	#ifdef SERVER
353	#define VARIANT 0
354	#else
355	#define VARIANT 1
356	#endif
357	#endif
358	
359	  if (SWITCH_Q >= 1 && SWITCH_Q <= 999) {
360	    int     idxV[MAXWARRIOR], scrV[MAXWARRIOR], i;
361	
362	    set_reg('W', (long) warriors);        /* 'W' used in score calculation */
363	    for (i = 0; i < warriors; ++i) {
364	      scrV[i] = score(i);
365	      idxV[i] = i;
366	    }
367	    if (SWITCH_o)
368	      sort_by_score(idxV, scrV);
369	    if (SWITCH_Q <= warriors)
370	      return scrV[idxV[SWITCH_Q - 1]];
371	    else if (SWITCH_Q >= 101 && SWITCH_Q <= 100 + warriors)
372	      return idxV[SWITCH_Q - 101] + 1;
373	    else
374	      return -1;                /* unknown -Q argument */
375	  } else
376	    switch (SWITCH_Q) {
377	    case 1000:
378	      return PMARSVER;                /* version */
379	    case 1001:
380	      return VARIANT;                /* SERVER, GRAPHX, etc. */
381	    case 1002:
382	      return PMARSVER * 10 + VARIANT;        /* a combination of the two */
383	    case 1003:                        /* core address size (int or short) */
384	      return sizeof(ADDR_T);
385	    case 2000:                        /* how many warriors share a P-space */
386	#ifdef PSPACE
387	      return warriors - pspP + 1;
388	#else
389	      return -1;
390	#endif
391	    default:
392	      return -1;                /* unknown -Q argument */
393	    }
394	}
