398	pspace_init()
399	{
400	  int     i, j;
401	  for (i = 0; i < warriors; ++i) {
402	    if (warrior[i].pSpaceIndex == UNSHARED)
403	      warrior[i].pSpaceIndex = pspP++;
404	    else if (warrior[i].pSpaceIndex == PIN_APPEARED) {        /* PIN appeared and
405	                                                         * unmatched */
406	      warrior[i].pSpaceIndex = pspP;
407	      for (j = i + 1; j < warriors; ++j)
408	        if (warrior[i].pSpaceIDNumber == warrior[j].pSpaceIDNumber)
409	          warrior[j].pSpaceIndex = pspP;
410	      ++pspP;
411	    }                                /* else: pSpace already shared, don't
412	                                 * increment pspP */
413	  }
414	  /* allocate space */
415	  for (i = 0; i < warriors; ++i) {
416	    warrior[i].lastResult = coreSize - 1;        /* unlikely number */
417	    if (pSpace[j = warrior[i].pSpaceIndex] == NULL &&
418	#ifdef DOS16
419	        ((pSpace[j] = (ADDR_T far *) farcalloc(pSpaceSize, sizeof(ADDR_T))) == NULL)) {
420	#else
421	    ((pSpace[j] = (ADDR_T *) calloc(pSpaceSize, sizeof(ADDR_T))) == NULL)) {
422	#endif
423	      errout(outOfMemory);
424	      Exit(MEMERR);
425	    }
426	  }
